@Component({
    selector: 'app-form-pm-negocio',
    imports: [
        GenericFormComponent,
    ],
    templateUrl: './form-pm-negocio.component.html',
    styleUrl: './form-pm-negocio.component.css'
})
export class FormPmNegocioComponent {
  form: Form = FORM_DEF
  formConditionals = FORM_CONDITIONALS
  datoPersonaMoral?: DatoPersonaMoral
  credito_id?: number
  showVerificar: boolean = false
  formValidator: Validator = {
    required: true    
  }
  credito?: Credito
  verificacionCredito?: VerificacionCredito
  constructor(
    private utils: UtilsService,
    private route: ActivatedRoute,
    public datoPersonaMoralController: DatoPersonaMoralService,    
    public creditoFormUtils:CreditoFormUtilsService,
    private cdr: ChangeDetectorRef
  ) { }

  ngOnInit() {
    console.log(this.form)
    this.route.parent?.parent?.paramMap.subscribe(async (params) => {
      const id = this.utils.intOrNull(params.get('credito_id'))
      if (id) {
        this.credito_id = id
        this.datoPersonaMoral = await this.datoPersonaMoralController.first({
          credito_id: id
        }, [
          'creditos',
          'accionistas',
          'diasLaborales',
          'telefonos',
          'PersonasMoralesActividadesEconomicas'
        ])
        this.credito = this.datoPersonaMoral?.creditos
      }
    })
  }
}
