import { Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { InversionTipo } from '../../../models/inversion.tipo.model';
import { InversionDetalleComponent } from "../inversion-detalle/inversion-detalle.component";
import { InversionTipoDetalle } from '../../../models/inversion.tipo.detalle.model';
import { CurrencyPipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { InversionTipoService } from '../../../controllers/inversion.tipo.service';

@Component({
    selector: 'app-inversion-tipo',
    imports: [
    InversionDetalleComponent,
    FormsModule,
    CurrencyPipe
],
    templateUrl: './inversion-tipo.component.html',
    styleUrl: './inversion-tipo.component.css'
})
export class InversionTipoComponent {
  @Input() inversionTipo!:InversionTipo&{id:number}
  @Input() inversionTipoChange= new EventEmitter<InversionTipo>()
  @Output() deleted = new EventEmitter<boolean>()
  @Input() disabled=false

  edit:boolean=false
  isLoading:boolean=false
  isDeleting:boolean=false
  

  detalles:InversionTipoDetalle[]=[]
  opciones= ['MERCANCIA E INSUMOS','MOBILIARIO Y/O EQUIPO DE OPERACION','INFRAESTRUCTURA']
  showDetalles:boolean=false

  constructor(
    private inversionTipoController: InversionTipoService,
  ){}

  ngOnChanges(changes:SimpleChanges){
    if(changes['inversionTipo']){
      this.detalles= this.inversionTipo.inversiones_tipos_detalles??[]
      if(this.inversionTipo.id==0) this.edit=true;
    }
  }

  public async save(){
    this.isLoading=true
    const res= (await this.inversionTipoController.createOrUpdate(this.inversionTipo))!
    if(res){
      this.inversionTipo.id=res.id
    }
    if(!this.inversionTipo.inversiones_tipos_detalles){
      this.inversionTipo.inversiones_tipos_detalles=[]
    }
    this.edit=false
    this.isLoading=false
  }

  public async delete(){
    this.isDeleting=true
    if(!this.inversionTipo.id){
      this.deleted.emit()
      this.isDeleting=false
      return 
    }
    const res= await this.inversionTipoController.switch(this.inversionTipo)
    if(res){
      this.isDeleting=false
      this.deleted.emit()
    }
  }

  public nuevoDetalle(){
    this.showDetalles=true
    if(!this.inversionTipo.inversiones_tipos_detalles){
      this.inversionTipo.inversiones_tipos_detalles=[]
    }
    this.inversionTipo.inversiones_tipos_detalles.unshift({
      inversion_tipo_id: this.inversionTipo.id??0,
      usuario_id: 0,
      monto_solicitado:0,
      nombre: '',
      id: 0,
      deleted_at: null,
      created_at: '',
      updated_at: null
    })
    this.inversionTipoChange.emit(this.inversionTipo)
  }

  public totalTipo():number{
    return this.inversionTipo.inversiones_tipos_detalles?.reduce((acc,item)=>{
      return acc+item.monto_solicitado
    },0)??0
  }

  public localDeleteDetalle(detalle: InversionTipoDetalle){
    const index= this.inversionTipo.inversiones_tipos_detalles?.indexOf(detalle)??-1
    if(index>-1){
      this.inversionTipo.inversiones_tipos_detalles?.splice(index,1)
    }
  }
}
