import { ChangeDetectorRef, Component } from '@angular/core';
import { AutocompleteFieldComponent } from "../../../../shared/generic-form/autocomplete-field/autocomplete-field.component";
import { DatosPersonalesFormComponent } from "../../../../catalogos/datos-personales/datos-personales-form/datos-personales-form.component";
import { DatoPersonal } from '../../../../models/dato.personal.model';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { DatoPersonalService } from '../../../../controllers/dato.personal.service';
import { UtilsService } from '../../../../services/utils.service';
import { DatePipe } from '@angular/common';
import { Credito } from '../../../../models/credito.model';
import { CreditoService } from '../../../../controllers/credito.service';
import { TablaLocalComponent } from "../../../../shared/tabla-local/tabla-local.component";
import { DataViewSectionComponent } from '../../../../shared/data-view-section/data-view.component';

@Component({
    selector: 'app-form-aval-credito',
    imports: [
    AutocompleteFieldComponent,
    DataViewSectionComponent,
    TablaLocalComponent
],
    templateUrl: './form-aval-credito.component.html',
    styleUrl: './form-aval-credito.component.css'
})
export class FormAvalCreditoComponent {
  credito?:Credito
  datoPersonal?:DatoPersonal
  showCreate:boolean=false
  isFormalizado: boolean = false
  avalCredito= (row:DatoPersonal) =>{
    return '(total creditos: '+row.creditos?.length +')'
  }
  constructor(
    private utils:UtilsService, 
    private creditoController: CreditoService, 
    private dpController:DatoPersonalService, 
    private route:ActivatedRoute,
    private cdr: ChangeDetectorRef
  ){}

  ngOnInit(){
    this.route.parent?.parent?.paramMap.subscribe(async (param)=>{
      const id= this.utils.intOrNull(param.get('credito_id'))
      if(id){
        this.credito= await this.creditoController.find(id)
        if(this.credito?.aval_id){
          this.checkAndDisableForm()
          this.setDatosPersonales(this.credito.aval_id)
        }
      }
    })
  }

  checkAndDisableForm() {
    if (this.credito?.formalizado_fecha) {
      this.isFormalizado = true;
      this.cdr.detectChanges();
    }
  }

  async setDatosPersonales(id:string|number|null){
    if(typeof id =='number'){
      this.datoPersonal = await this.dpController.find(id, ['creditos', 'creditosPf', 'creditosPm', 'telefonosPersonales','ciudades','estado_nacimiento'], false);
      return
    }
    this.datoPersonal=undefined
  }

  async updateCredito(){
    if(this.credito && this.datoPersonal){
      this.credito.aval_id= this.datoPersonal.id
      this.creditoController.update(this.credito.id,this.credito)
    }
  }
}