import { Component } from '@angular/core';
import { UtilsService } from '../../../../services/utils.service';
import { InversionProgramaService } from '../../../../controllers/inversion.programa.service';
import { ActivatedRoute } from '@angular/router';
import { InversionPrograma } from '../../../../models/inversion.programa.model';
import { Credito } from '../../../../models/credito.model';
import { CreditoService } from '../../../../controllers/credito.service';
import { InversionTipoService } from '../../../../controllers/inversion.tipo.service';
import { InversionTipoDetalleService } from '../../../../controllers/inversion.tipo.detalle.service';

import { FormsModule } from '@angular/forms';
import { InversionProgramaComponent } from "../../../../shared/inversion-programa/inversion-programa.component";

@Component({
    selector: 'app-form-programa-inversion',
    imports: [
    FormsModule,
    InversionProgramaComponent
],
    templateUrl: './form-programa-inversion.component.html',
    styleUrl: './form-programa-inversion.component.css'
})
export class FormProgramaInversionComponent {
  inversionPrograma?: InversionPrograma | Partial<InversionPrograma>={
    inversion_tipos:[]
  }
  isFormalizado: boolean = false;

  credito?:Credito
  constructor(
    public utils:UtilsService, 
    public inversionProgramaController: InversionProgramaService,
    private route: ActivatedRoute, 
    private creditoController:CreditoService,
    public inversionTipoController: InversionTipoService, 
    public inversionTipoDetalleController: InversionTipoDetalleService,
  ){}

  ngOnInit(){
    this.route.parent?.parent?.paramMap.subscribe(async (param)=>{
      const id= this.utils.intOrNull(param.get('credito_id'))
      if(id){
        this.credito= await this.creditoController.find(id,['inversionesProgramas.inversionTipos.inversionesTiposDetalles','productosFinancieros.plazos' ])
        if(this.credito?.inversiones_programas){
          console.log(this.credito)
          this.inversionPrograma= this.credito.inversiones_programas          
        }
        this.isFormalizado = this.credito?.formalizado_fecha !== null
      }
    })
  }
}
