@Component({
    selector: 'app-form-pf-negocio',
    imports: [GenericFormComponent,],
    templateUrl: './form-pf-negocio.component.html',
    styleUrl: './form-pf-negocio.component.css'
})
export class FormPfNegocioComponent {
  form: Form = FORM_DEF
  formValidator: Validator = {
    required: true
  }
  formConditionals=FORM_CONDITIONALS
  datoPersonaFisica?: DatoPersonaFisica
  verificacionCredito?: VerificacionCredito
  negocio?: Negocio
  credito?: Credito
  showCreate: boolean = false
  constructor(
    private utils: UtilsService, private datoPersonaFisicaController: DatoPersonaFisicaService,
    public negocioController: NegocioService, private route: ActivatedRoute,
    private fieldTypes: FieldTypesService,
    private creditoController: CreditoService,
    public creditoFormUtils: CreditoFormUtilsService
  ) { }

  ngOnInit() {
    this.route.parent?.parent?.paramMap.subscribe(async (param) => {
      const id = this.utils.intOrNull(param.get('credito_id'))
      if (id) {
        this.credito = await this.creditoController.find(id)
        this.datoPersonaFisica = await this.datoPersonaFisicaController.findOrCreate({
          credito_id: id
        })
        if (this.datoPersonaFisica?.negocio_id) {
          this.setNegocio(this.datoPersonaFisica.negocio_id)
        }
      }
    })
  }

  async setNegocio(id: number | null | string) {
    if (typeof id == 'number') {
      this.negocio = await this.negocioController.find(id,
        [
          'negociosActividadesEconomicas',
          "negociosDiasLaborables",
        ], false
      )
      this.updateDatoPersonaFisica()
      return
    }
    this.negocio = undefined
  }

  async updateDatoPersonaFisica() {
    if (this.datoPersonaFisica && this.negocio && !this.datoPersonaFisica.negocio_id) {
      this.datoPersonaFisica.negocio_id = this.negocio.id
      this.datoPersonaFisicaController.update(this.datoPersonaFisica.id, this.datoPersonaFisica)
    }
  }

  test(value: any) {
    console.log(value)
  }

  checkValues(data: Negocio) {
    const isDisabled = data.local_tipo === 'PROPIO';
    const keysToUpdate = ['local_renta_mensual', 'local_contrato_inicio', 'local_contrato_fin'];

    this.form.forEach((field) => {
      if (this.fieldTypes.isFormGroup(field)) {
        field.fields.forEach((innerField) => {
          if (this.fieldTypes.isFormField(innerField) && keysToUpdate.includes(innerField.key)) {
            this.updateField(innerField, isDisabled);
          }
        });
      }
    });
  }

  private updateField(innerField: any, isDisabled: boolean) {
    innerField.validator = {
      ...innerField.validator,
      disabled: isDisabled
    };
    if (innerField.key === 'local_renta_mensual' && isDisabled) {
      innerField.value = 0;
    }
  }
}
