import { Component } from '@angular/core';
import { Credito } from '../../../../models/credito.model';
import { CreditoService } from '../../../../controllers/credito.service';
import { ActivatedRoute } from '@angular/router';
import { UtilsService } from '../../../../services/utils.service';
import { FileInputComponent } from '../../../../shared/file-input/file-input.component';

import { formatoTransparencia } from '../../../../services/documentosLegales/contratos/contrato_credito_formato_transparencia.service';
import { cartaProtesta } from '../../../../services/documentosLegales/contratos/contrato_credito_carta_bajo_protesta.service';
import { avisoPrivacidad } from '../../../../services/documentosLegales/contratos/contrato_credito_aviso_privacidad.service';
import { solicitudPersonaFisica } from '../../../../services/documentosLegales/contratos/contrato_solicitud_pf.service';
import { solicitudPersonaMoral } from '../../../../services/documentosLegales/contratos/contrato_solicitud_pm.service';
import { ProductoFinancieroDocumento } from '../../../../models/producto.financiero.documento.model';
import { CreditoProductoFinancieroDocumento } from '../../../../models/creditos.productos.financieros.documento';
import { CreditoProductoFinancieroDocumentoService } from '../../../../controllers/credito.producto.financiero.documento.service';

@Component({
    selector: 'app-documentos-credito',
    imports: [
    FileInputComponent
],
    templateUrl: './documentos-credito.component.html',
    styleUrl: './documentos-credito.component.css'
})
export class DocumentosCreditoComponent {
  credito?: Credito
  isFormalizado: boolean = false

  constructor(
    private creditoController: CreditoService,
    private route: ActivatedRoute,
    private utils: UtilsService,
    public formatoTransferencia: formatoTransparencia,
    public cartaProtestaSoltero: cartaProtesta,
    public contratoPrivacidad: avisoPrivacidad,
    public solicitudPf: solicitudPersonaFisica,
    public solicitudPm: solicitudPersonaMoral,
    private creditoDocumentoController: CreditoProductoFinancieroDocumentoService,
  ) { }

  ngOnInit() {
    this.route.parent?.parent?.paramMap.subscribe(async (params) => {
      const id = this.utils.intOrNull(params.get('credito_id'))
      if (id) {
        await this.setCredito(id)
        console.log(this.credito)
        this.revisarDocumentosNuevos()
      }
      this.isFormalizado = this.credito?.formalizado_fecha !== null
    })
  }

  public async setCredito(id: number) {
    this.credito = await this.creditoController.find(id, [
      'productosFinancieros.documentos.documento',
      'documentos.productosFinancierosDocumentos.documento',
      'datosPersonaFisica',
      'datosPersonasMorales',
    ])
  }

  private async revisarDocumentosNuevos() {
    if (!this.credito) return;
    const documentosNuevos = this.documentosNuevos()
    if (documentosNuevos.length) {
      console.info('CREANDO DOCUMENTOS NUEVOS')
      const nuevosDocumentosRequeridos: CreditoProductoFinancieroDocumento[] = []
      documentosNuevos.forEach((dpf) => {
        nuevosDocumentosRequeridos.push({
          productos_financieros_documento_id: dpf.id,
          credito_id: this.credito!.id,
          usuario_id: 0,
          id: 0,
          created_at: ''
        })
      })
      await this.creditoDocumentoController.multipleNews(nuevosDocumentosRequeridos)
      this.setCredito(this.credito!.id)
    }
    console.info('NO HAY DOCUMENTOS NUEVOS PARA CREAR')
  }

  private documentosNuevos(): ProductoFinancieroDocumento[] {
    const documentosProductoFinanciero = this.credito?.productos_financieros?.documentos ?? [];
    const documentosCredito = this.credito?.documentos ?? [];

    // Encontrar documentos en productos financieros que no están en crédito
    const nuevosDocumentos = documentosProductoFinanciero.filter(docPF => {
      // Verificar si no existe un documento con el mismo ID en documentosCredito
      return !documentosCredito.some(docC => docC.productos_financieros_documento_id === docPF.id);
    });

    // Si hay al menos un documento nuevo, retornar true
    return nuevosDocumentos
  }
}
