import { Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { InversionTipoDetalle } from '../../../models/inversion.tipo.detalle.model';
import { FormsModule } from '@angular/forms';
import { InversionTipoDetalleService } from '../../../controllers/inversion.tipo.detalle.service';
import { CurrencyPipe } from '@angular/common';

@Component({
    selector: 'app-inversion-detalle',
    imports: [
    FormsModule,
    CurrencyPipe
],
    templateUrl: './inversion-detalle.component.html',
    styleUrl: './inversion-detalle.component.css'
})
export class InversionDetalleComponent {
  @Input() detalle!:InversionTipoDetalle
  @Input() isFormalizado:boolean = false;
  @Output() delete = new EventEmitter()

  edit:boolean=false
  isLoading:boolean=false

  constructor(
    private detalleController:InversionTipoDetalleService
  ){}

  ngOnChanges(changes:SimpleChanges){
    if(changes['detalle']){
      if(this.detalle.id==0) this.edit=true;
    }
  }

  public async saveDetalle(){
    this.isLoading=true
    const res= (await this.detalleController.createOrUpdate(this.detalle))

    if(res){
      this.edit=false
    }
    this.isLoading=false
  }

  public async deleteDetalle(){
    if(this.detalle.id>0){
      const res= await this.detalleController.switch(this.detalle)
      if(res) this.delete.emit();
      return
    }
    this.delete.emit()
  }
  
}
