import { Component, ViewChild } from '@angular/core';
import { UtilsService } from '../../../../services/utils.service';
import { AutocompleteFieldComponent } from "../../../../shared/generic-form/autocomplete-field/autocomplete-field.component";
import { ActivatedRoute, RouterLink } from '@angular/router';
import { CreditoReferenciaPersonal } from '../../../../models/credito.referencia.personal';
import { Credito } from '../../../../models/credito.model';
import { CreditoService } from '../../../../controllers/credito.service';

import { TablaComponent, TableDefinition } from "../../../../shared/tabla/tabla.component";
import { CreditoReferenciaPersonalService } from '../../../../controllers/credito.referencia.personal.service';
import { SimpleVerificacionCreditoComponent } from "../simple-verificacion-credito/simple-verificacion-credito.component";
import { ReferenciaPersonal } from '../../../../models/referencia.personal.model';
import { Form, GenericFormComponent } from '../../../../shared/generic-form/generic-form.component';
import { REFERENCIA_PERSONAL_FORM } from '../../../../catalogos/referencias-personales/form-referencias-personales/form-referencias-personales.component';
import { ReferenciaPersonalService } from '../../../../controllers/referencia.personal.service';

const FORM_DEF:Form=[
  {
    key:'nombre',
    label:'Nombre',
    style:{
      div:"col-12 col-sm-6 col-md"
    },
    type:'text'
  },
  {
    key:'parentezco',
    label:'Parentesco',
    apiUrl:'api/parentesco',
    keyList:'id',
    keyDetalle:'nombre',
    style:{
      div:"col-12 col-sm-6 col-md"
    },
    nuevoRedirect:'/catalogos/parentescos/nuevo'
  },
  {
    key:'telefono',
    label:'Telefono',
    style:{
      div:"col-12 col-sm-6 col-md"
    },
    type:'text',
  },
  {
    key:'domicilio',
    label:'Domicilio',
    type:'text',
    style:{
      div:"col-12 col-sm-6 col-md"
    },
  },
]

@Component({
    selector: 'app-form-referencias-credito',
    imports: [
    GenericFormComponent
],
    templateUrl: './form-referencias-credito.component.html',
    styleUrl: './form-referencias-credito.component.css'
})
export class FormReferenciasCreditoComponent {
  form= FORM_DEF
  credito?:Credito
  idReferencia?:number
  edit?:ReferenciaPersonal
  showForm:boolean=false
  isFormalizado:boolean=false
  constructor(
    private utils:UtilsService, 
    private route:ActivatedRoute, 
    private creditoController: CreditoService,
    public referenciaController: ReferenciaPersonalService,
    public creditoReferenciaPersonalController: CreditoReferenciaPersonalService,

  ){}

  ngOnInit(){
    this.route.parent?.parent?.paramMap.subscribe(async (params)=>{
      const id= this.utils.intOrNull(params.get('credito_id'))
      if(id){
        this.credito= await this.creditoController.find(id,['referenciasPersonales.parentescos'])
      }
      this.isFormalizado = this.credito?.formalizado_fecha !== null;
    })
  }
  nuevaReferencia(){
    this.showForm=!this.showForm
    this.edit=undefined
  }

  async onSavedReferencia(referencia:ReferenciaPersonal){
    const find= this.credito?.referencias_personales?.find((ref)=> ref.id==referencia.id)
    console.log(find)
    if(find){
      this.credito= await this.creditoController.find(this.credito!.id,['referenciasPersonales.parentescos'])
      this.showForm=false
      this.edit=undefined
      return
    }
    const nuevo= await this.creditoReferenciaPersonalController.new({credito_id:this.credito?.id, referencias_personal_id:referencia.id})
    if(nuevo) this.credito= await this.creditoController.find(this.credito!.id,['referenciasPersonales.parentescos'])
      this.showForm=false
  }

  async deleteReferencia(refe:ReferenciaPersonal){
    const res= await this.referenciaController.switch(refe)
    if(res){
      this.credito= await this.creditoController.find(this.credito!.id,['referenciasPersonales.parentescos'])
    }
  }

  editReferencia(refe:ReferenciaPersonal){
    this.showForm=true
    this.edit=refe
  }
}
