import { ChangeDetectorRef, Component } from '@angular/core';
import { AutocompleteFieldComponent } from "../../../../../shared/generic-form/autocomplete-field/autocomplete-field.component";
import { UtilsService } from '../../../../../services/utils.service';
import { DatoPersonaFisica } from '../../../../../models/dato.persona.fisica.model';
import { DatoPersonal } from '../../../../../models/dato.personal.model';
import { DatoPersonalService } from '../../../../../controllers/dato.personal.service';

import { ActivatedRoute } from '@angular/router';
import { TablaLocalComponent } from '../../../../../shared/tabla-local/tabla-local.component';
import { DatoPersonaFisicaService } from '../../../../../controllers/dato.persona.fisica.service';
import { DataViewSectionComponent } from "../../../../../shared/data-view-section/data-view.component";
import { LoginCliente } from '../../../../../clientes/auth/auth.service';
import { LocalStorageService } from '../../../../../services/localStorage/local-storage.service';
import { Credito } from '../../../../../models/credito.model';
import { CreditoService } from '../../../../../controllers/credito.service';

@Component({
    selector: 'app-form-pf-datos-personales',
    imports: [
    AutocompleteFieldComponent,
    TablaLocalComponent,
    DataViewSectionComponent
],
    templateUrl: './form-pf-datos-personales.component.html',
    styleUrl: './form-pf-datos-personales.component.css'
})
export class FormPfDatosPersonalesComponent {
  credito?:Credito
  datoPersonaFisica?:DatoPersonaFisica
  datoPersonal?:DatoPersonal
  userClient?:LoginCliente | null
  isFormalizado = false;  

  autoacompleteMapFunction= (row:DatoPersonal) =>{
    return row.apellido_paterno+' '+row.apellido_paterno+' '+'(total creditos: '+row.creditos?.length +')'
  }

  constructor(
    private utils:UtilsService,
    private datoPersonaFisicaController: DatoPersonaFisicaService,
    private dpController:DatoPersonalService,
    private creditoController: CreditoService,
    private route:ActivatedRoute,
    private storage:LocalStorageService,
    private cdr: ChangeDetectorRef,      
  ){}

  ngOnInit(){
    this.userClient = this.storage.getClienteUser();
    this.route.parent?.parent?.paramMap.subscribe(async (param)=>{
      const id= this.utils.intOrNull(param.get('credito_id'))
      if(id){
        this.credito = await this.creditoController.find(id)
        this.checkAndDisableForm();
        this.datoPersonaFisica = await this.datoPersonaFisicaController.findOrCreate({
          credito_id:id,
          deleted_at:null,
        })
        if(this.datoPersonaFisica?.datos_personal_id){
          this.setDatosPersonales(this.datoPersonaFisica.datos_personal_id)
        }
      }
    })
  }

  checkAndDisableForm() {
    if (this.credito?.formalizado_fecha) {
      this.isFormalizado = true;
      this.cdr.detectChanges();
    }
  }

  async setDatosPersonales(id:string|number|null){
    if(typeof id =='number'){
      this.datoPersonal = await this.dpController.find(id, ['creditos', 'creditosPf', 'creditosPm', 'telefonosPersonales','ciudades','estado_nacimiento'], false);
      return
    }
    this.datoPersonal=undefined
  }

  async updateCredito(){
    if(this.datoPersonaFisica && this.datoPersonal){
      this.datoPersonaFisica.datos_personal_id= this.datoPersonal.id
      this.datoPersonaFisicaController.update(this.datoPersonaFisica.id, this.datoPersonaFisica)
    }
  }
}
