import { Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { InversionPrograma } from '../../models/inversion.programa.model';
import { InversionProgramaService } from '../../controllers/inversion.programa.service';
import { FormsModule } from '@angular/forms';
import { ProductoFinanciero } from '../../models/producto.financiero.model';
import { CurrencyPipe } from '@angular/common';
import { InversionTipo } from '../../models/inversion.tipo.model';
import { InversionTipoComponent } from "./inversion-tipo/inversion-tipo.component";

@Component({
    selector: 'app-inversion-programa',
    imports: [
    FormsModule,
    CurrencyPipe,
    InversionTipoComponent
],
    templateUrl: './inversion-programa.component.html',
    styleUrl: './inversion-programa.component.css'
})
export class InversionProgramaComponent {
  @Input() inversion_programa_id?:number
  @Output() inversion_programa_idChange= new EventEmitter<number>()
  @Input() inversionPrograma?: InversionPrograma
  @Output() inversionProgramaChange = new EventEmitter<InversionPrograma>()
  @Input() credito_id:number=0
  @Input() productoFinanciero?: ProductoFinanciero
  @Input() disabled=false;
  
  plazosOptions:number[]=[]
  plazo_solicitado_meses?:number
  inversionTipos:InversionTipo[]=[]

  constructor(
    private inversionProgramaController: InversionProgramaService,
  ){}

  ngOnChanges(changes:SimpleChanges){
    if(changes['inversionPrograma']){
      this.setInversionesTipo()
    }
    if(changes['productoFinanciero']){
      this.setPlazos()
    }
  }

  public async updateProgramaInversion(){
    console.log(this.credito_id);
    this.inversionPrograma=await this.inversionProgramaController.createOrUpdate({
      credito_id:this.credito_id,
      ...this.inversionPrograma,
      plazo_solicitado_meses:this.plazo_solicitado_meses
    })
    this.inversionProgramaChange.emit(this.inversionPrograma)
  }

  private setInversionesTipo(){
    if(!this.inversionPrograma) return
    if(this.inversionPrograma.inversion_tipos){
      this.inversionTipos= this.inversionPrograma.inversion_tipos
    }
    console.log(this.inversionTipos, this.inversionPrograma)
  }

  private setPlazos(){
    this.plazosOptions= this.productoFinanciero?.plazos?.map((plazo)=> plazo.plazo_meses)??[]
    this.plazo_solicitado_meses=this.inversionPrograma?.plazo_solicitado_meses??0
  }

  nuevoInversionTipo(){
    this.inversionTipos.unshift({
      inversion_programa_id      : this.inversionPrograma?.id ?? 0,
      usuario_id                 : 0,
      inversion_tipo             : 'MERCANCIA E INSUMOS',
      id                         : 0,
      deleted_at                 : null,
      created_at                 : '',
      updated_at                 : null,
      inversiones_tipos_detalles : [],
    });
  }

  public total():number{
    const total= this.inversionTipos.
    reduce((acc,item)=>{
      return acc+(item.inversiones_tipos_detalles??[]).
      reduce((acc,item)=>{
        return acc+item.monto_solicitado
      },0)
    },0)??0

    return total? total : (this.inversionPrograma?.monto_solicitado??0)
  }

  deleteInversionTipo(tipo:InversionTipo){
    this.inversionTipos.splice(this.inversionTipos.indexOf(tipo),1)
  }
}
