import { ChangeDetectorRef, Component } from '@angular/core';
import { AutocompleteFieldComponent } from "../../../../../shared/generic-form/autocomplete-field/autocomplete-field.component";
import { UtilsService } from '../../../../../services/utils.service';
import { DatoPersonal } from '../../../../../models/dato.personal.model';
import { DatoPersonalService } from '../../../../../controllers/dato.personal.service';

import { ActivatedRoute, RouterLink } from '@angular/router';
import { DataViewComponent } from '../../../../../shared/data-view/data-view.component';
import { TablaLocalComponent } from '../../../../../shared/tabla-local/tabla-local.component';
import { DatoPersonaMoral } from '../../../../../models/dato.persona.moral.model';
import { DatoPersonaMoralService } from '../../../../../controllers/dato.persona.moral.service';
import { DataViewSectionComponent } from "../../../../../shared/data-view-section/data-view.component";
import { LocalStorageService } from '../../../../../services/localStorage/local-storage.service';
import { LoginCliente } from '../../../../../clientes/auth/auth.service';
import { CreditoService } from '../../../../../controllers/credito.service';
import { Credito } from '../../../../../models/credito.model';

@Component({
    selector: 'app-form-pf-datos-personales',
    imports: [
    AutocompleteFieldComponent,
    TablaLocalComponent,
    DataViewSectionComponent
],
    templateUrl: './form-representante-legal.component.html',
    styleUrl: './form-representante-legal.component.css'
})
export class FormRepresentanteLegalComponent {
  datoPersonaMoral?:DatoPersonaMoral
  userClient?:LoginCliente | null
  credito?:Credito
  isFormalizado: boolean = false;

  datoPersonal?:DatoPersonal
  autoacompleteMapFunction= (row:DatoPersonal) =>{
    return row.apellido_paterno+' '+row.apellido_paterno+' '+'(total creditos: '+row.creditos?.length +')'
  }

  constructor(
    private creditoController: CreditoService,
    private utils:UtilsService,
    private datoPersonaMoralController: DatoPersonaMoralService,
    private dpController:DatoPersonalService,
    private route:ActivatedRoute,
    private storage:LocalStorageService,
    private cdr: ChangeDetectorRef
  ){}

  ngOnInit(){
    this.userClient = this.storage.getClienteUser();
    this.route.parent?.parent?.paramMap.subscribe(async (param)=>{
      const id= this.utils.intOrNull(param.get('credito_id'))
      if(id){
        this.credito = await this.creditoController.find(id)
        this.datoPersonaMoral= await this.datoPersonaMoralController.first({
          credito_id:id
        },[],false)
        if(this.datoPersonaMoral?.representante_legal_id){
          this.setDatosPersonales(this.datoPersonaMoral.representante_legal_id)
        }
        this.checkAndDisableForm()
      }
    })
  }

  checkAndDisableForm() {
    if (this.credito?.formalizado_fecha) {
      this.isFormalizado = true;
      this.cdr.detectChanges();
    }
  }

  /**
   * Fetches and sets the personal data (`DatoPersonal`) for a given ID.
   *
   * This function retrieves the personal data from the `DatoPersonalService` based on the provided ID.
   * If the ID is a number, it fetches the associated `DatoPersonal` object, including related credit data.
   * If the ID is not a number (e.g., null or a string), it sets `datoPersonal` to `undefined`.
   *
   * @param {string | number | null} id - The ID of the personal data to fetch. Can be a number, string, or null.
   * @returns {Promise<void>} - A promise that resolves once the data is fetched and set (or cleared).
   */
  async setDatosPersonales(id: string | number | null): Promise<void> {
    if (typeof id === 'number') {
      this.datoPersonal = await this.dpController.find(id, ['creditos', 'creditosPf', 'creditosPm', 'telefonosPersonales','ciudades','estado_nacimiento'], false);
      return;
    }
    this.datoPersonal = undefined;
  }

  async updateCredito(){
    if(this.datoPersonaMoral && this.datoPersonal){
      this.datoPersonaMoral.representante_legal_id= this.datoPersonal.id
      this.datoPersonaMoralController.update(this.datoPersonaMoral.id, this.datoPersonaMoral)
    }
  }
}
