@Component({
    selector: 'app-form-datos-fiscales',
    imports: [
    FormsModule,
    GenericFormComponent
],
    templateUrl: './form-datos-fiscales.component.html',
    styleUrl: './form-datos-fiscales.component.css'
})
export class FormDatosFiscalesComponent {

  credito?: Credito;
  datosFiscales?: DatosFiscales;
  datosPersonales?: any;
  form: Form = FORM_DEF;

  constructor(
    private creditoController: CreditoService,
    private route: ActivatedRoute,
    private utils: UtilsService,
    public controller: DatosFiscalesService,
    public creditoFormUtils: CreditoFormUtilsService,
    private cdr: ChangeDetectorRef
  ) {
    this.route.parent?.parent?.paramMap.subscribe(async (params) => {
      const id = this.utils.intOrNull(params.get('credito_id'));
      if (id) {
        this.credito = await this.creditoController.find(id, [
          'datosPersonaFisica',
          'datosPersonaFisica.datosPersonales',
          'datosPersonaFisica.datosPersonales.datosFiscales',
          'datosPersonasMorales',
          'datosPersonasMorales.datosFiscales'
        ]);

        if (this.credito) {
          this.datosPersonales = this.utils.getDatosGeneralesFromCredito(this.credito);          
          // this.datosFiscales = this.utils.getDatosFiscalesFromCredito(this.credito);
          console.log(this.datosPersonales);
          if (this.datosPersonales) {
            if (this.datosPersonales.datos_fiscales) {
              this.datosFiscales = { ...this.datosPersonales.datos_fiscales };
            } else {
              // -- llanear los datos fiscales algunos datos
              const df: Partial<DatosFiscales> = {
                rfc: this.datosPersonales.rfc,
                primer_nombre: this.datosPersonales.nombre !== undefined ? this.datosPersonales.nombre : this.datosPersonales.razon_social,
                primer_apellido: this.datosPersonales.apellido_paterno ? this.datosPersonales.apellido_paterno : '',
                segundo_apellido: this.datosPersonales.apellido_materno ? this.datosPersonales.apellido_materno : '',
                codigo_postal: this.datosPersonales.codigo_postal || '',
                calle: '',
                colonia: '',
                municipio: this.datosPersonales.localidad || '',
              };
              this.datosFiscales = { ...this.datosPersonales.datos_fiscales, ...df };
            }
          }          
        }
      }
    });
  }
}
